'use client'

import { useEffect, useRef, useState, KeyboardEvent, ClipboardEvent, ChangeEvent } from 'react'
import { motion, AnimatePresence } from 'motion/react'
import { cn } from '@/lib/utils/cn'
import { Surface } from '@/components/stepwise/primitives/surface'

export interface OtpInputProps {
  length?     : number
  /** 'numeric' → digits only (default). 'alphanumeric' → letters + digits (security code). */
  type?       : 'numeric' | 'alphanumeric'
  value?      : string
  /** Initial value for uncontrolled use - ignored once `value` is passed. */
  defaultValue?: string
  onChange?   : (value: string) => void
  /** Fires once when every box is filled. */
  onComplete? : (code: string) => void
  /** Shows the resend line; called when the user taps "Resend code". */
  onResend?   : () => void
  /** Seconds before resend unlocks. Default 30. */
  resendAfter?: number
  error?      : boolean
  disabled?   : boolean
  className?  : string
}

// One cell's edge. The resting state is the library-wide hairline - the same
// token Segment, Input and Toast read - so a cell matches every other field on
// the page. Error and focus get their own tokens. Each carries an inline
// fallback: the registry ships source, not this site's stylesheet, so a bare
// var() would arrive with no border at all.
const cellBorder = (error: boolean, focused: boolean) =>
  error
    ? { width: 2, opacity: 1, color: 'var(--ui-border-error, #fb7185)' }
    : focused
      ? { width: 2, opacity: 1, color: '#38bdf8' } // sky-400, matching every other focus indicator in the library
      : { width: 1, opacity: 1, color: 'var(--ui-border, rgb(138 138 141 / 0.23))' }

export function OtpInput({
  length      = 6,
  type        = 'numeric',
  value,
  defaultValue = '',
  onChange,
  onComplete,
  onResend,
  resendAfter = 30,
  error       = false,
  disabled    = false,
  className,
}: OtpInputProps) {
  const isAlpha = type === 'alphanumeric'
  // keep only allowed characters; security codes are upper-cased for legibility
  const sanitize = (s: string) =>
    isAlpha ? s.replace(/[^a-zA-Z0-9]/g, '').toUpperCase() : s.replace(/\D/g, '')
  const [internal, setInternal] = useState(defaultValue)
  const [focusedIdx, setFocusedIdx] = useState<number | null>(null)
  const [countdown, setCountdown] = useState(resendAfter)
  const val     = value ?? internal
  const digits  = val.split('').slice(0, length)
  const refs    = useRef<(HTMLInputElement | null)[]>([])
  const doneFor = useRef<string | null>(null)

  // resend countdown - only runs when a resend handler exists
  useEffect(() => {
    if (!onResend || countdown <= 0) return
    const t = setTimeout(() => setCountdown(c => c - 1), 1000)
    return () => clearTimeout(t)
  }, [onResend, countdown])

  // fire onComplete exactly once per full code
  useEffect(() => {
    if (val.length === length && doneFor.current !== val) {
      doneFor.current = val
      onComplete?.(val)
    }
    if (val.length < length) doneFor.current = null
  }, [val, length, onComplete])

  const update = (next: string) => {
    if (value === undefined) setInternal(next)
    onChange?.(next)
  }

  const handleChange = (i: number, e: ChangeEvent<HTMLInputElement>) => {
    const raw = sanitize(e.target.value)
    if (!raw) return
    const char = raw[raw.length - 1]
    const arr  = digits.slice()
    arr[i] = char
    for (let j = i + 1; j < length; j++) arr[j] = arr[j] ?? ''
    update(arr.join('').slice(0, length))
    if (i < length - 1) refs.current[i + 1]?.focus()
  }

  const handleKeyDown = (i: number, e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace') {
      e.preventDefault()
      if (digits[i]) {
        const arr = digits.slice()
        arr[i] = ''
        update(arr.join(''))
      } else if (i > 0) {
        const arr = digits.slice()
        arr[i - 1] = ''
        update(arr.join(''))
        refs.current[i - 1]?.focus()
      }
    } else if (e.key === 'ArrowLeft' && i > 0) {
      refs.current[i - 1]?.focus()
    } else if (e.key === 'ArrowRight' && i < length - 1) {
      refs.current[i + 1]?.focus()
    }
  }

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault()
    const pasted = sanitize(e.clipboardData.getData('text')).slice(0, length)
    update(pasted)
    refs.current[Math.min(pasted.length, length - 1)]?.focus()
  }

  const resend = () => {
    setCountdown(resendAfter)
    update('')
    refs.current[0]?.focus()
    onResend?.()
  }

  return (
    <div className={cn('flex flex-col items-center gap-4', className)}>
      {/* the row shakes as one when error flips on */}
      <motion.div
        role="group"
        aria-label={`${length}-digit verification code`}
        className="flex gap-2"
        animate={error ? { x: [0, -7, 6, -4, 3, 0] } : { x: 0 }}
        transition={{ duration: 0.4, ease: 'easeInOut' }}
      >
        {Array.from({ length }, (_, i) => {
          const isFilled  = !!digits[i]
          const isFocused = focusedIdx === i

          return (
            <motion.div
              key={i}
              className="relative"
              animate={{ y: isFocused ? -2 : 0, scale: isFilled && !isFocused ? 1 : isFocused ? 1.04 : 1 }}
              transition={{ type: 'spring', duration: 0.25, bounce: 0 }}
            >
              {/* Surface, not a bare rounded input: every rounded element in
                  the library is a squircle, and a ring/box-shadow would be
                  clipped away by the corner mask anyway - so the edge is a
                  middleBorder stroked along the squircle path itself. */}
              <Surface
                radius={14}
                lisse={{ middleBorder: cellBorder(error, isFocused) }}
                className={cn(
                  'h-14 w-11 transition-colors duration-150',
                  isFocused ? 'bg-white dark:bg-zinc-800' : 'bg-zinc-50 dark:bg-zinc-900',
                  disabled && 'opacity-40',
                )}
              >
                <input
                  ref={el => { refs.current[i] = el }}
                  type="text"
                  inputMode={isAlpha ? 'text' : 'numeric'}
                  pattern={isAlpha ? '[a-zA-Z0-9]*' : '[0-9]*'}
                  autoCapitalize={isAlpha ? 'characters' : 'off'}
                  autoComplete="one-time-code"
                  spellCheck={false}
                  maxLength={1}
                  value={digits[i] ?? ''}
                  disabled={disabled}
                  onChange={e => handleChange(i, e)}
                  onKeyDown={e => handleKeyDown(i, e)}
                  onPaste={handlePaste}
                  onFocus={e => { setFocusedIdx(i); e.target.select() }}
                  onBlur={() => setFocusedIdx(null)}
                  aria-label={`Digit ${i + 1}`}
                  aria-invalid={error || undefined}
                  className={cn(
                    'h-full w-full bg-transparent text-center outline-none',
                    'text-[22px] font-semibold tracking-[-0.01em]',
                    'text-transparent caret-transparent', // real glyph is the animated span below
                    disabled && 'cursor-not-allowed',
                  )}
                />
              </Surface>
              {/* digit pops in with a blurred spring; input text is transparent */}
              <span className="pointer-events-none absolute inset-0 flex items-center justify-center">
                <AnimatePresence mode="popLayout" initial={false}>
                  {isFilled && (
                    <motion.span
                      key={digits[i] + i}
                      initial={{ opacity: 0, scale: 0.4, filter: 'blur(4px)', y: 6 }}
                      animate={{ opacity: 1, scale: 1, filter: 'blur(0px)', y: 0 }}
                      exit={{ opacity: 0, scale: 0.4, filter: 'blur(4px)' }}
                      transition={{ type: 'spring', duration: 0.3, bounce: 0 }}
                      className={cn(
                        'text-[22px] font-semibold tracking-[-0.01em]',
                        error ? 'text-rose-500' : 'text-zinc-900 dark:text-zinc-100',
                      )}
                    >
                      {digits[i]}
                    </motion.span>
                  )}
                </AnimatePresence>
              </span>
            </motion.div>
          )
        })}
      </motion.div>

      {/* resend line - countdown, then a live link */}
      {onResend && (
        <div className="flex items-center gap-1 text-[13px] text-zinc-400 dark:text-zinc-500">
          <span>Didn&apos;t get the code?</span>
          {countdown > 0 ? (
            <span className="tabular-nums">
              Resend in 0:{String(countdown).padStart(2, '0')}
            </span>
          ) : (
            <button
              type="button"
              onClick={resend}
              className="font-medium text-sky-500 transition-colors hover:text-sky-600 dark:hover:text-sky-400"
            >
              Resend code
            </button>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { forwardRef } from 'react'
import { SmoothCorners, type SmoothCornersOwnProps, type SmoothCornerOptions } from '@lisse/react'
import { cn } from '@/lib/utils/cn'

interface SurfaceProps extends React.HTMLAttributes<HTMLDivElement> {
  radius?: number
  smoothing?: number
  /** Override for per-corner config - takes precedence over radius/smoothing. */
  corners?: SmoothCornerOptions
  // `className` isn't part of SmoothCornersOwnProps - it comes from the
  // polymorphic element props (ComponentPropsWithoutRef<E>) instead - but
  // it's a legitimate, commonly-needed passthrough (e.g. forcing `h-full`
  // through the SmoothCorners wrapper), so it's added back explicitly here.
  lisse?: Omit<SmoothCornersOwnProps, 'corners'> & { className?: string }
}

export const Surface = forwardRef<HTMLDivElement, SurfaceProps>(({
  radius = 12,
  smoothing = 0.6,
  corners,
  className,
  children,
  lisse,
  ...rest
}, ref) => {
  return (
    <SmoothCorners corners={corners ?? { radius, smoothing }} {...lisse}>
      <div ref={ref} className={cn(className)} {...rest}>
        {children}
      </div>
    </SmoothCorners>
  )
})

Surface.displayName = 'Surface'

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
